// Process Google Sheets data to create summary
const items = $input.all();
const data = items[0].json.values || [];

// Calculate summary statistics
const totalRows = data.length;
const headers = data[0] || [];
const dataRows = data.slice(1);

// Create summary object
const summary = {
  totalRecords: totalRows - 1, // excluding header
  columns: headers.length,
  lastUpdated: new Date().toISOString(),
  columnNames: headers,
  sampleData: dataRows.slice(0, 5) // first 5 rows as sample
};

// Generate HTML email content
const emailContent = `
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; margin: 20px; }
    h1 { color: #333; }
    h2 { color: #666; }
    table { border-collapse: collapse; width: 100%; margin: 20px 0; }
    th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
    th { background-color: #f2f2f2; }
    .summary-box { background-color: #f9f9f9; padding: 15px; border-radius: 5px; margin: 10px 0; }
  </style>
</head>
<body>
  <h1>📊 Daily Google Sheet Summary</h1>

  <div class="summary-box">
    <h2>📈 Summary Statistics</h2>
    <ul>
      <li><strong>Total Records:</strong> ${summary.totalRecords}</li>
      <li><strong>Columns:</strong> ${summary.columns}</li>
      <li><strong>Last Updated:</strong> ${new Date(summary.lastUpdated).toLocaleString()}</li>
    </ul>
  </div>

  <h2>📋 Column Names</h2>
  <p>${summary.columnNames.join(', ')}</p>

  <h2>🔍 Sample Data (First 5 Rows)</h2>
  <table>
    <tr>
      ${summary.columnNames.map(col => `<th>${col}</th>`).join('')}
    </tr>
    ${summary.sampleData.map(row => 
      `<tr>${row.map(cell => `<td>${cell || ''}</td>`).join('')}</tr>`
    ).join('')}
  </table>

  <hr>
  <p><em>This is an automated daily summary from your Google Sheet.</em></p>
</body>
</html>
`;

// Generate plain text version
const plainTextContent = `
DAILY GOOGLE SHEET SUMMARY
==========================

Summary Statistics:
- Total Records: ${summary.totalRecords}
- Columns: ${summary.columns}
- Last Updated: ${new Date(summary.lastUpdated).toLocaleString()}

Column Names:
${summary.columnNames.join(', ')}

Sample Data (First 5 Rows):
${summary.sampleData.map((row, index) => 
  `Row ${index + 1}: ${row.join(' | ')}`
).join('\n')}

---
This is an automated daily summary from your Google Sheet.
`;

return {
  json: {
    summary,
    emailContent,
    plainTextContent,
    subject: `Daily Sheet Summary - ${summary.totalRecords} records (${new Date().toLocaleDateString()})`
  }
};
